INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261106-afghan-deportations', 'judge-caproni-blocks-deportations-detained-afghans-afghanistan-pakistan', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Federal judge temporarily blocks the deportation of detained Afghans to Afghanistan or Pakistan', 'U.S. District Judge Valerie Caproni''s order, issued on Tuesday, Nov. 3, runs through Saturday, Nov. 7. Government lawyers told the court no deportation flights were planned before then.', 'A federal judge in New York has temporarily barred the Trump administration from deporting detained Afghan nationals to Afghanistan or Pakistan.

U.S. District Judge Valerie Caproni issued the temporary restraining order on Tuesday, Nov. 3, ABC News reported. It is in effect through Saturday, Nov. 7.

## What the government told the court

A Justice Department filing indicated that "dozens" of Afghan immigrants had been expected to be deported during the week of Monday, Nov. 2, according to ABC News. Government lawyers then told the court that ICE had no planned or confirmed charter or commercial flights for those removals through the end of the week. Caproni ordered the administration to stick to that statement and noted that arranging such flights takes weeks. ICE declined to comment on specific removal operations.

Democracy Now reported that deportation flights had been expected to start as early as that week.

## Who is affected

Advocates say hundreds of Afghans are being held in ICE detention in Louisiana, ABC News reported. Some of those facing deportation may be relatives of Afghans who worked alongside the U.S. military. Advocates warn that people sent back could face persecution under Taliban rule.

Shawn VanDiver, president of the advocacy group AfghanEvac, called the order "a reprieve, not a resolution." Rep. Scott Peters said lawmakers would keep pressing for answers about Pakistan''s role and for legislation to protect Afghans from deportation, according to ABC News.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/8/83/Daniel_Patrick_Moynihan_U.S._Courthouse,_Manhattan,_New_York_(7237347688).jpg', 'The Daniel Patrick Moynihan U.S. Courthouse in Manhattan (file). Photo: Flickr via Wikimedia Commons (editor: confirm the photographer and license on the Commons file page before approving)', 'licensed', 'newsroom', 'content/2026-11-06.sql', 6, 0, 'newsroom-assistant', '2026-11-06T10:45:00.000Z', '2026-11-06T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261106-afghan-deportations-src1', 'bd-20261106-afghan-deportations', 'Judge temporarily blocks deportation of Afghan nationals', 'https://abcnews.com/US/judge-temporarily-blocks-deportation-afghan-nationals/story?id=137822689', 'ABC News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-06T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-06. Editor to confirm.', 'newsroom-assistant', '2026-11-06T10:45:00.000Z');
