INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261106-bruins-penguins', 'bruins-beat-penguins-6-2-zacha-two-goals-james-hagens-injured', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Zacha scores twice as the Bruins rout the Penguins 6-2 for a third straight win, and James Hagens leaves hurt', 'Boston (12-4-1) led 3-1 after the first period at PPG Paints Arena on Thursday, Nov. 5. Michael DiPietro made 16 saves for his fourth straight win.', 'Pavel Zacha scored twice and the Bruins beat the Pittsburgh Penguins 6-2 on Thursday, Nov. 5, in Pittsburgh. It was Boston''s third straight win.

Mark Kastelic, Elias Lindholm, Morgan Geekie and Fraser Minten also scored, NHL.com reported. Geekie added an assist and has goals in three straight games. David Pastrnak and JJ Peterka had two assists each. Michael DiPietro made 16 saves for his fourth straight win, Boston Hockey Now reported.

## How it got away from Pittsburgh

Boston led 3-1 after one period and 5-2 after two, CBS Sports reported. Zacha and Minten each scored on a 2-on-1. Geekie scored on a partial breakaway after a poor Pittsburgh line change. Lindholm scored after an Erik Karlsson turnover in the Penguins'' own zone. Karlsson finished at minus-4.

Justin Brazeau and Nick Robertson scored for Pittsburgh. Arturs Silovs made 18 saves. Sidney Crosby had no points and stays tied with Marcel Dionne for sixth on the NHL''s career scoring list with 1,771 points, CBS Sports noted.

## Hagens injury

James Hagens left early in the third period after a cross-check to the back from Samuel Girard, NHL.com reported. He limped to the bench, went down the tunnel and did not return, according to Boston Hockey Now. The team did not give an update on his condition.

## Where they stand

The Bruins are 12-4-1 and have won 10 of their last 13. They have earned points in seven straight trips to Pittsburgh, dating to Nov. 1, 2022, CBS Sports reported. The Penguins (5-9-2) have lost four straight.

Boston has Friday off, practices on Saturday and hosts the Florida Panthers on Sunday afternoon, Nov. 8, according to Boston Hockey Now.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/1/18/PPG_Paints_Arena_interior.jpg', 'Inside PPG Paints Arena, home of the Pittsburgh Penguins (file). Photo: Wikimedia Commons (editor: confirm the photographer and license on the Commons file page before approving)', 'licensed', 'newsroom', 'content/2026-11-06.sql', 7, 0, 'newsroom-assistant', '2026-11-06T10:45:00.000Z', '2026-11-06T10:45:00.000Z');
