INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261106-patriots-maye-award', 'drake-maye-afc-offensive-player-of-month-aj-brown-hunter-henry-miss-practice-packers', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Drake Maye is named AFC Offensive Player of the Month as A.J. Brown and Hunter Henry miss practice again before the Packers game', 'Maye led the NFL with 12 touchdown passes in October. The 5-3 Patriots host the 5-3 Packers at Gillette Stadium on Sunday, Nov. 8.', 'Patriots quarterback Drake Maye was named the AFC Offensive Player of the Month for October on Thursday, Nov. 5, the team announced.

Maye completed 90 of 134 passes for 1,199 yards in October. He led the NFL with 12 touchdown passes and a 119.0 passer rating, and he threw at least three touchdowns in each of the month''s four games, according to Patriots.com. New England went 3-1 in October, starting with a 29-26 win at Buffalo. It is Maye''s first Player of the Month award and the first for a Patriots offensive player since Tom Brady in November 2017.

The turnaround has been sharp. MassLive, via Yahoo Sports, reported that Maye threw for 585 yards, one touchdown and six interceptions in the first three weeks. Since Week 4 he has 1,398 yards, 14 touchdowns, two interceptions and a 122.2 passer rating.

## Thursday practice

- **A.J. Brown (knee)** missed a fourth straight practice and is on track to miss a second straight game, MassLive reported.
- **Hunter Henry (foot)** missed practice on Wednesday and Thursday. He played only eight snaps in the Sunday, Nov. 1, win over Miami, Heavy reported.
- **Christian Barmore** returned on Thursday after missing Wednesday with an illness.
- **TreVeyon Henderson** (illness) and cornerback **Marcus Jones** also missed Thursday''s practice.
- **Mack Hollins** is back at practice but is still on injured reserve. He must be activated before he can play, MassLive noted.

The Patriots'' final injury report is due on Friday, Nov. 6. Brady will call Sunday''s game at Gillette Stadium for Fox, his first Patriots game as a broadcaster, MassLive reported.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Patriots_Hall_of_Fame_in_Foxborough,_Massachusetts_(flickr_6730211623)_2010.jpg', 'The Patriots Hall of Fame at Patriot Place in Foxborough, Massachusetts, 2010 (file). Photo: Flickr via Wikimedia Commons (editor: confirm the photographer and license on the Commons file page before approving)', 'licensed', 'newsroom', 'content/2026-11-06.sql', 7, 0, 'newsroom-assistant', '2026-11-06T10:45:00.000Z', '2026-11-06T10:45:00.000Z');
