INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261106-jaguars-ravens', 'jaguars-beat-ravens-33-10-thursday-night-football-joe-fagnano-first-start', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Jaguars beat the depleted Ravens 33-10 on Thursday Night Football as Joe Fagnano struggles in his first start', 'Jacksonville (6-2) forced three turnovers in the rain in Baltimore on Thursday, Nov. 5. The Ravens (4-5) have lost four straight, with Lamar Jackson on injured reserve.', 'The Jacksonville Jaguars beat the Baltimore Ravens 33-10 on Thursday, Nov. 5, at M&T Bank Stadium. Baltimore was down to its third-string quarterback.

Lamar Jackson went on injured reserve with a right thumb injury and will miss at least three games, and Tyler Huntley is out with turf toe, ESPN reported. That left rookie Joe Fagnano to make his first NFL start. He completed 10 of 18 passes for 60 yards and threw two interceptions.

Trevor Lawrence went 16 of 26 for 242 yards and a touchdown, a 50-yard catch by Parker Washington before halftime, DAZN reported. Bhayshul Tuten and Chris Rodriguez Jr. ran for touchdowns, and Cam Little kicked four field goals, tying his career high. Baltimore''s three turnovers led to 13 Jacksonville points. Justice Hill''s 65-yard touchdown run was the Ravens'' only touchdown.

## Records and milestones

- Jacksonville is 6-2 and leads the AFC South, according to DAZN. It has scored more than 30 points in three straight games, ESPN reported.
- Baltimore is 4-5 after its fourth straight loss. It has been held under 14 points in four straight games and has lost three straight by 20 or more, both firsts in team history, ESPN said.
- Derrick Henry ran for 57 yards and passed LaDainian Tomlinson for seventh place on the NFL''s career rushing list, DAZN reported.

ESPN reported that the Ravens are close to finalizing a trade for quarterback Jacoby Brissett. Jacksonville hosts Tennessee on Sunday, Nov. 15, and Baltimore hosts the Los Angeles Chargers on Monday, Nov. 16.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/d/dc/M%26T_Bank_Stadium_DoD.jpg', 'M&T Bank Stadium in Baltimore, home of the Ravens (file). Photo: U.S. Department of Defense via Wikimedia Commons, public domain (editor: confirm on the Commons file page)', 'public_domain', 'newsroom', 'content/2026-11-06.sql', 6, 0, 'newsroom-assistant', '2026-11-06T10:45:00.000Z', '2026-11-06T10:45:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261106-jaguars-ravens-src1', 'bd-20261106-jaguars-ravens', 'Trevor Lawrence, Jags pull away from Joe Fagnano, Ravens on TNF', 'https://www.espn.com/nfl/story/_/id/50395188/jaguars-ravens-thursday-night-football-joe-fagnano', 'ESPN', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-06T10:45:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-06. Editor to confirm.', 'newsroom-assistant', '2026-11-06T10:45:00.000Z');
