INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261106-nba-thursday', 'warriors-beat-heat-120-100-curry-sixth-straight-win-suns-beat-magic-booker-30', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Curry hits six 3-pointers as the Warriors win a sixth straight, and Devin Booker scores 30 in the Suns'' win over the Magic', 'Results from Thursday, Nov. 5: Warriors 120, Heat 100, and Suns 117, Magic 104.', 'Two NBA games were played on Thursday, Nov. 5.

## Warriors 120, Heat 100

Stephen Curry scored 29 points and made six 3-pointers as Golden State beat Miami at Chase Center in San Francisco, ESPN reported. It was the Warriors'' sixth straight win, and they are 6-3.

Yaxel Lendeborg added 17 points, eight rebounds and six assists. Draymond Green had a season-high 11 assists, and Georges Niang scored 13 off the bench. A 26-9 run in the third quarter put the game away.

For Miami (3-6), Davion Mitchell scored 22 points with eight assists. Giannis Antetokounmpo had 20 points and 14 rebounds, and Bam Adebayo had 18 points and 10 rebounds.

## Suns 117, Magic 104

Devin Booker scored 30 points and Dillon Brooks added 24 as Phoenix beat Orlando at home, ESPN reported. Miles Bridges had 18 points and a season-high 13 rebounds. The Suns made 17 of 34 3-pointers and scored 36 points off Orlando''s 25 turnovers.

Wendell Carter Jr. led the Magic with 27 points on 10-of-12 shooting and 13 rebounds. Franz Wagner had 15 points and 15 assists. Phoenix is 2-5, and Orlando is 2-6.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/b/bb/Chase_Center_-_Warriors.jpg', 'Chase Center, home of the Golden State Warriors, in San Francisco (file). Photo: Wikimedia Commons (editor: confirm the photographer and license on the Commons file page before approving)', 'licensed', 'newsroom', 'content/2026-11-06.sql', 5, 0, 'newsroom-assistant', '2026-11-06T10:45:00.000Z', '2026-11-06T10:45:00.000Z');
