INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261106-red-sox-silver-slugger', 'red-sox-willson-contreras-wilyer-abreu-silver-slugger-finalists', 'newsroom', 'news_story', 'mlb', 'EDITORIAL_REVIEW', 0, 'Willson Contreras and Wilyer Abreu are the Red Sox'' two Silver Slugger finalists', 'The pair combined for 51 home runs and led Boston in homers and RBIs. The winners will be announced on Tuesday, Nov. 17.', 'Two Red Sox hitters are finalists for the American League Silver Slugger Awards, NESN reported on Thursday, Nov. 5.

First baseman Willson Contreras and outfielder Wilyer Abreu combined for 51 home runs in 2026. They ranked first and second on the team in both home runs and RBIs, according to NESN.

Contreras is up against Baltimore''s Pete Alonso at first base. Abreu is one of several outfield finalists, a group that also includes Cody Bellinger, Chandler Simpson, Mike Trout, Randy Arozarena, Tristan Peters, Chase DeLauter, Riley Greene and Jac Caglianone.

The Silver Slugger winners will be announced on Tuesday, Nov. 17.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/0/0d/Fenway_Park_Green_Monster_1998-19.jpg', 'Fenway Park''s Green Monster in Boston, 1998 (file). Photo: Wikimedia Commons (editor: confirm the photographer and license on the Commons file page before approving)', 'licensed', 'newsroom', 'content/2026-11-06.sql', 5, 0, 'newsroom-assistant', '2026-11-06T10:45:00.000Z', '2026-11-06T10:45:00.000Z');
